// Tokenize takes bytes as input and lexes it into
// a list of tokens that can be parsed as a Caddyfile.
// Also takes a filename to fill the token's File as
// the source of the tokens, which is important to
// determine relative paths for `import` directives.
//
// The input is treated as raw file bytes: a leading UTF-8
// byte order mark is consumed as a file marker, and CR LF,
// lone CR and LF are all treated as line separators. After
// that normalization, token text and positions are the same
// regardless of the line ending encoding used. The input is
// not retained, so later changes to the caller's buffer do
// not affect returned tokens, and calls share no state.
func Tokenize(input []byte, filename string) ([]Token, error) {
	l := lexer{}
	if err := l.init(input, filename); err != nil {
		return nil, err
	}
	var tokens []Token
	for {
		found, err := l.next()
		if err != nil {
			return nil, err
		}
		if !found {
			break
		}
		l.token.File = filename
		tokens = append(tokens, l.token)
	}
	return tokens, nil
